html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--surface);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 6px;
  text-decoration: none;
  border: 2px solid var(--focus);
  z-index: 100;
}
.skip-link:focus {
  top: 8px;
}

main.card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px;
  max-width: 480px;
  width: 100%;
  border: 1px solid var(--border);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0 0 24px;
  color: var(--muted);
}

.required-legend {
  font-size: 0.875rem;
  color: var(--muted);
  margin: 0 0 16px;
}

.req {
  color: var(--error);
  font-weight: 700;
}

.form-field {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 12px;
  row-gap: 4px;
  align-items: start;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
}

.form-field.is-invalid {
  border-color: var(--error);
  background: var(--error-bg);
}

.form-field input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin: 2px 0 0;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.form-field label {
  grid-column: 2;
  cursor: pointer;
  font-weight: 500;
}

.form-field a {
  color: var(--accent);
  text-decoration: underline;
}
.form-field a:hover {
  color: var(--accent-hover);
}

.helper {
  grid-column: 2;
  font-size: 0.875rem;
  color: var(--muted);
  margin: 0;
}

.error {
  grid-column: 1 / -1;
  font-size: 0.875rem;
  color: var(--error);
  margin: 8px 0 0;
  font-weight: 500;
}

.actions {
  margin-top: 20px;
  display: flex;
  justify-content: flex-end;
}

button[type="submit"] {
  font: inherit;
  font-weight: 600;
  background: var(--accent);
  color: var(--accent-contrast);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 10px 18px;
  cursor: pointer;
  min-height: 44px;
  transition: background-color 0.15s ease;
}
button[type="submit"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.status {
  margin-top: 16px;
  padding: 12px 14px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text);
}

@media (forced-colors: active) {
  .form-field,
  main.card,
  button[type="submit"],
  .status {
    border: 1px solid CanvasText;
  }
  button[type="submit"] {
    background: ButtonFace;
    color: ButtonText;
  }
  :focus-visible {
    outline: 3px solid Highlight;
  }
}
