          </p>
          {error && (
            <p id={errorId} className="error" role="alert">
              {error}
            </p>
          )}
        </div>

        <div className="actions">
          <button type="submit">Accept and continue</button>
        </div>

        <div aria-live="polite" className="sr-live">
          {submitted && (
            <p className="status">Thanks — your agreement has been recorded.</p>
          )}
        </div>
      </form>
    </main>
  );
}

