function ConsentForm() {
  const [checked, setChecked] = useState(false);
  const [error, setError] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const checkboxRef = useRef(null);

  const id = useId();
  const checkboxId = `${id}-agree`;
  const helperId = `${id}-help`;
  const errorId = `${id}-error`;

  const describedBy = error ? `${helperId} ${errorId}` : helperId;

  function handleSubmit(e) {
    e.preventDefault();
    if (!checked) {
      setError("Error: You must agree to the terms of use to continue.");
      setSubmitted(false);
      checkboxRef.current?.focus();
      return;
    }
    setError("");
    setSubmitted(true);
  }

  function handleChange(e) {
    setChecked(e.target.checked);
    if (e.target.checked && error) setError("");
  }

  return (
    <main className="card" id="main">
      <h1>Confirm your agreement</h1>
      <p className="lede">
        Please review and accept our terms of use before continuing.
      </p>
      <p className="required-legend">
        <span className="req" aria-hidden="true">*</span> indicates a required field.
      </p>

      <form noValidate onSubmit={handleSubmit}>
        <div className={`form-field${error ? " is-invalid" : ""}`}>
          <input
            ref={checkboxRef}
            id={checkboxId}
            type="checkbox"
            required
            checked={checked}
            onChange={handleChange}
            aria-describedby={describedBy}
            aria-invalid={error ? "true" : "false"}
          />
          <label htmlFor={checkboxId}>
            I agree to the{" "}
            <a href="/terms" target="_blank" rel="noopener noreferrer">
              terms of use
            </a>{" "}
            <span className="req" aria-hidden="true">*</span>
            <span className="visually-hidden">(required)</span>
          </label>
          <p id={helperId} className="helper">
