const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const url = 'file://' + path.resolve(process.argv[2]);
  const b = await chromium.launch();
  const page = await b.new_page ? null : null;
  const ctx = await b.newContext();
  const p = await ctx.newPage();
  const errors = [];
  p.on('pageerror', e => errors.push(String(e)));
  p.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await p.goto(url, { waitUntil: 'load' });
  // wait for React to mount
  await p.waitForSelector('main.card', { timeout: 5000 });
  await p.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await p.evaluate(async () => await window.axe.run());
  await b.close();
  const wcag = r.violations.filter(v => !(v.tags || []).includes('best-practice'));
  const bp = r.violations.filter(v => (v.tags || []).includes('best-practice'));
  console.log(JSON.stringify({
    pageErrors: errors,
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) })),
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();

